#Requires -Version 5.1
# fix-rrhh-errores-ts.ps1
# Errores TypeScript que causaban el crash al entrar en RRHH:
# 1. Pencil no importado -> TS2304 -> crash en runtime
# 2. newR[0].id tipado como never -> TS2339
# 3. Pagina [id] obsoleta con errores (permisosLoaded, canDo("ver"))
#    -> se elimina porque ya no se usa (sustituida por el modal)

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix errores TS RRHH" -ForegroundColor Cyan

# Escribir page.tsx corregido
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), $bytes)
Write-Host "  OK: page.tsx corregido" -ForegroundColor Green

# Eliminar la pagina [id] obsoleta si existe
$idDir = Join-Path $RepoPath "src\app\maestros\recursos-humanos\[id]"
if (Test-Path $idDir) {
    Remove-Item -Recurse -Force $idDir
    Write-Host "  OK: carpeta [id] eliminada" -ForegroundColor Green
} else {
    Write-Host "  INFO: carpeta [id] ya no existia" -ForegroundColor Gray
}

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("Pencil")) { Write-Host "  OK: Pencil importado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("viewRecord")) { Write-Host "  OK: modal vista presente" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: RRHH errores TS Pencil + eliminar pagina [id] obsoleta"'
Write-Host "  git push"
